import{_ as a,o as s,c as t,a5 as i}from"./chunks/framework.BwlBv862.js";const h=JSON.parse('{"title":"Internationalisation et accessibilité","description":"","frontmatter":{"title":"Internationalisation et accessibilité","docId":"developer.i18n-accessibility","translationKey":"developer.i18n-accessibility","locale":"fr","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"2c74fcefd1d28353b1135c547b2e3e6ae852af8b683350011732d10c364f9323","translationRevision":"41485a8df0080d774338fa0108074bc4db296a320e297d992e15302286b66542","order":120},"headers":[],"relativePath":"fr/developer/i18n-accessibility.md","filePath":"fr/developer/i18n-accessibility.md","lastUpdated":1794611623000}'),n={name:"fr/developer/i18n-accessibility.md"};function l(o,e,r,c,d,u){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="internationalization-and-accessibility" tabindex="-1">Internationalisation et accessibilité <a class="header-anchor" href="#internationalization-and-accessibility" aria-label="Permalink to &quot;Internationalisation et accessibilité {#internationalization-and-accessibility}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Ajouter un écran qui reste compréhensible dans les langues prises en charge et utilisable au clavier, au toucher et avec les technologies d’assistance. Lisez les <a href="./frontend.html">couches de l’interface</a> et utilisez les composants partagés existants. Les langues de l’application à l’exécution et les éditions publiées de la documentation sont des systèmes distincts.</p><h2 id="add-localized-content" tabindex="-1">Ajouter du contenu localisé <a class="header-anchor" href="#add-localized-content" aria-label="Permalink to &quot;Ajouter du contenu localisé {#add-localized-content}&quot;">​</a></h2><p>Le catalogue de l’application se trouve dans <code>src/web/shared/i18n/</code>. L’anglais est la langue de repli typée ; les autres catalogues pris en charge sont chargés à la demande. <code>activateLocale</code> charge les messages choisis et met à jour <code>document.documentElement.lang</code>. Enregistrez la préférence de langue via le store de langue existant plutôt qu’une autre clé de stockage local.</p><ol><li>Ajoutez la clé sémantique du message au catalogue anglais et aux catalogues/modules équivalents pris en charge.</li><li>Gardez stables les identifiants d’API, chemins d’événements et identifiants de ressources stockés ; traduisez leurs libellés visibles.</li><li>Utilisez l’interpolation pour le texte variable et les utilitaires d’internationalisation partagés pour les valeurs affichées.</li><li>Pour les descripteurs de plugins, utilisez le contrat de texte localisé existant <code>{default,i18key}</code> et les catalogues fusionnés par l’hôte. Ne rendez jamais en HTML des chaînes traduites ou fournies par un plugin.</li></ol><h2 id="preserve-control-semantics" tabindex="-1">Préserver la sémantique des commandes <a class="header-anchor" href="#preserve-control-semantics" aria-label="Permalink to &quot;Préserver la sémantique des commandes {#preserve-control-semantics}&quot;">​</a></h2><p>Préférez <code>BaseTextField</code>, <code>BaseFormRow</code>, <code>BaseDialog</code>, les onglets et les composants d’état. Un texte indicatif ne remplace pas un libellé accessible. Les boutons d’icône nécessitent un nom localisé. La validation doit identifier le champ et exposer son état invalide ; ne communiquez pas une erreur uniquement par la couleur. Préservez le retour du focus des boîtes de dialogue, le comportement d’Échap, la sélection clavier et les contours de focus visibles.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i18n</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> catalogs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BaseDialog</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-lint</span></span></code></pre></div><p>Pour l’examen manuel, parcourez tout le parcours avec Tab, ouvrez/fermez la boîte de dialogue, changez de langue pendant son ouverture et répétez à faible largeur. Les actions d’état apparaissant au survol doivent aussi apparaître au focus clavier et rester disponibles au toucher.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Résultat attendu et état {#expected-result-and-status}&quot;">​</a></h2><p>Le typage des catalogues et les contrôles de parité détectent les clés manquantes ; les composants partagés fournissent des comportements clavier et ARIA implémentés. Ils ne constituent pas une certification globale d’accessibilité de tous les écrans composés. Rankings reste masqué même si des chaînes traduites existent.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Récupération {#recovery}&quot;">​</a></h2><p>Si du texte non traduit apparaît, vérifiez le chargement différé des catalogues et l’orthographe exacte des clés avant d’ajouter des replis anglais dans les composants. Si le focus disparaît, examinez la commande recevant les attributs transférés et la cible de retour de la boîte de dialogue. L’<a href="https://github.com/nglmercer/TikTools-app/blob/remake/src/web/shared/i18n/i18n.ts" target="_blank" rel="noreferrer">implémentation i18n</a> et les tests de composants définissent le comportement actuel ; les <a href="./components/">composants</a> expliquent les points d’entrée partagés.</p><h2 id="operational-details" tabindex="-1">Détails de fonctionnement <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Détails de fonctionnement {#operational-details}&quot;">​</a></h2><p>Détection : <code>tiktok-live-locale</code> sauvegardé → <code>navigator.languages</code> → anglais. <code>normalizeLocale</code> gère régions et <code>jp</code> → <code>ja</code>. Codes/régions : <code>en/en-US</code>, <code>es/es-ES</code>, <code>pt/pt-BR</code>, <code>fr/fr-FR</code>, <code>zh/zh-CN</code>, <code>ja/ja-JP</code> ; utilisez formatCount/formatDate d’<code>intl.ts</code>. <code>activateLocale</code> charge messages/lang ; <code>useLocaleStore().setLocale</code> persiste aussi et prépare les préférences au mieux. Utilisez le store dans les réglages. Anglais en fallback ; zh/ja chargent les messages hôte. Nouveau langage : supported-locales, loaders, catalogues/hôte, régions, tests préférences/clés/placeholders/pluriels/compilation et routes docs/site. Préservez IDs/API et paramètres.</p><p>Utilisez tokens espace/type/contrôle/focus/couches. Tout pointeur grossier ou largeur sous 700px porte les contrôles à 44px ; navigation sous 900px et lignes sous 600px sont indépendantes. Mouvement réduit annule les durées. Testez le tactile aussi sur écran large. L’app est sombre globalement ; la variante claire est réservée au JSON.</p><p>Clavier : onglets flèches/Home/End avec sélection automatique ; selects flèches/Home/End/Entrée et Échap annule ; menus rendent le focus. Dialogues en showModal natif, mais <code>closable=false</code> bloque Échap et fermer démonte le contenu. Gardez les brouillons chez le propriétaire et vérifiez focus initial/retour. Bouton icône exige <code>label</code> ; <code>hint</code>/tooltip explique sans nommer. Tooltip attend 500ms au survol/focus, ferme sur Échap et respecte le top layer. Vérifiez les flux clavier/assistance réels ; les unit tests ne certifient pas un écran entier.</p>`,18)])])}const g=a(n,[["render",l]]);export{h as __pageData,g as default};
